import{_ as l,l as i,o as e,c as s,v as o,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"CSE 与 GVN","description":"","frontmatter":{"title":"CSE 与 GVN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cse-gvn.md","filePath":"cs/cse-gvn.md","lastUpdated":1789023840000}'),h={name:"cs/cse-gvn.md"};function E(C,a,m,_,u,S){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="cse-与-gvn" tabindex="-1">CSE 与 GVN <a class="header-anchor" href="#cse-与-gvn" aria-label="Permalink to &quot;CSE 与 GVN&quot;">​</a></h1><div class="epigraph"><p>公共子表达式：同一运算算两次则复用。全局值编号给每个值一个类，按哈希把等价计算并成一个领导。</p><footer>—— 据 Cocke, Global Common Subexpression Elimination；Alpern, Wegman and Zadeck, Detecting Equality of Variables in Programs, 1988；Click, Global Value Numbering 整理</footer></div><p>上一课<a href="/cs/sccp">SCCP</a>处理常量这一格。缺口是<strong>结构相等</strong>：<code>a+b</code> 在两处出现，或经代数 <code>a+b</code> 与 <code>b+a</code>（若交换）。CSE 是数据流「可用表达式」的消除；GVN 用编号。主干<a href="/cs/available-expr">可用表达式</a>已给方程。本课钉 SSA 上的实践，不重推位向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用表达式：程序点上「若再算 \\(a+b\\) 则与先前同一」。局部 CSE 在基本块哈希表即可。全局：须支配——复用点被计算点支配，否则要插入或放弃。GVN：值编号，φ 与运算的合同。缺口是<strong>何时可删第二次运算</strong>，不是常量格。</p><p>Click 的 GVN 可与 SCCP 类似地乐观。代数化简（<code>x-x</code>）属同一遍或相邻遍。</p><h3 id="编号不是「名字字符串」" tabindex="-1">编号不是「名字字符串」 <a class="header-anchor" href="#编号不是「名字字符串」" aria-label="Permalink to &quot;编号不是「名字字符串」&quot;">​</a></h3><p><code>add x1, y1</code> 与 <code>add x2, y2</code> 仅当 \\(x\\)、\\(y\\) 编号相同才同号。SSA 使「同名」等价于「同值」对标量成立；内存不算，除非别名说只读。</p><p><span class="marginnote">Cocke 早期 CSE。AWZ 1988。Click 的 GVN。龙书 6.1.2 / 9.1。Appel 有局部值编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部：块内表，键为操作码+操作数编号。全局：RPO 遍历支配树，或 AWZ 的哈希。消除：第二次改成对领导的拷贝，再拷贝传播。</p>',11)),(e(),n(p,null,{default:t(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E8%BF%90%E7%AE%97%22%5D%20--%3E%20VN%5B%22%E5%80%BC%E7%BC%96%E5%8F%B7%22%5D%0A%20%20VN%20--%3E%20CSE%5B%22%E5%A4%8D%E7%94%A8%E9%A2%86%E5%AF%BC%22%5D%0A%20%20CSE%20--%3E%20COPY%5B%22%E6%8B%B7%E8%B4%9D%E4%BC%A0%E6%92%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 LICM：循环里不变的公共表达式先外提再编号，后课。不要对可能陷阱的运算（除零、load）在不可靠路径上复用——控制依赖。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>交换律：规范化操作数序（编号较小者在前）再哈希。浮点：交换律在 IEEE 下对 NaN/符号有坑，fast-math 才开。</p><p>PRE（部分冗余）后课：表达式在部分路径可用时插入使全局可用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写别名。后课默认：标量纯运算可 GVN。下一课 DCE/ADCE：编号后的死拷贝与死块。</p><p>也不把 CSE 当加密哈希碰撞问题；编号哈希冲突只影响编译期表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSE：复用已算的表达式；GVN 用值编号找等价。</li><li>支配决定全局复用点。</li><li>内存与浮点要额外纪律。</li><li>出处：Cocke；Alpern–Wegman–Zadeck, 1988；Click；龙书。</li></ul>',9))])}const f=l(h,[["render",E]]);export{A as __pageData,f as default};
